{\"title\": \"Field Activity Dashboard\", \"subtitle\": \"Para Sahya Program - Daily Children Reached & Village Visit Frequency\", \"_mode\": \"dashboard\", \"panels\": [{\"id\": \"p1\", \"kind\": \"kpi\", \"title\": \"Total Children Reached (Apr-Aug 2025)\", \"sql\": \"SELECT SUM(\\\"first_number\\\") as total FROM \\\"whatsapp_field_group_export_messages\\\" WHERE (message LIKE '%total%' OR message LIKE '%bacche%' OR message LIKE '%aaye%' OR message LIKE '%children%' OR message LIKE '%kids%')\", \"unit\": \"children\"}, {\"id\": \"p2\", \"kind\": \"line\", \"title\": \"Daily Children Reached Trend\", \"sql\": \"SELECT \\\"date\\\", \\\"first_number\\\" as children_reached FROM \\\"whatsapp_field_group_export_messages\\\" WHERE (message LIKE '%total%' OR message LIKE '%bacche%' OR message LIKE '%aaye%' OR message LIKE '%children%' OR message LIKE '%kids%') ORDER BY \\\"date\\\"\", \"x\": \"date\", \"y\": [\"children_reached\"]}, {\"id\": \"p3\", \"kind\": \"bar\", \"title\": \"Visit Frequency by Village\", \"sql\": \"SELECT \\\"village\\\", COUNT(*) as visit_count FROM \\\"village_visit_log\\\" GROUP BY 1 ORDER BY 2 DESC\", \"x\": \"village\", \"y\": [\"visit_count\"]}], \"narrative\": \"The dashboard shows field coordination activity from April to August 2025. Panel {{p1}} displays total children reached via WhatsApp updates. Panel {{p2}} tracks the daily trend of children reached. Panel {{p3}} summarizes village visit frequency across all visited villages.\"}
EOF"

